const SHEET_ID = '18pzNeHnhqmMX-FeT0AoPOd0aqOkcLK7yE-i1IfA5Sy4';
const SHEET_NAME = 'MASTER';
const CSV_URL = `https://docs.google.com/spreadsheets/d/${SHEET_ID}/gviz/tq?tqx=out:csv&sheet=${encodeURIComponent(SHEET_NAME)}`;

let CACHE = null;
let CACHE_AT = 0;

function parseCSV(text) {
  const rows = [];
  let row = [], cur = '', inQ = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inQ) {
      if (ch === '"') {
        if (text[i + 1] === '"') { cur += '"'; i++; }
        else inQ = false;
      } else cur += ch;
    } else {
      if (ch === '"') inQ = true;
      else if (ch === ',') { row.push(cur); cur = ''; }
      else if (ch === '\n') { row.push(cur); rows.push(row); row = []; cur = ''; }
      else if (ch !== '\r') cur += ch;
    }
  }
  if (cur !== '' || row.length) { row.push(cur); rows.push(row); }
  return rows;
}

function mapRow(r, h) {
  const get = (k) => { const i = h.indexOf(k); return i >= 0 ? (r[i] || '').trim() : ''; };
  return { e: get('Enroll'), n: get('Employee Name'), d: get('Designation'), c: get('Contact No'), wg: get('Workplace Group'), w: get('Workplace'), sbu: get('SBU Name') };
}

export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Cache-Control', 'no-store');
  if (req.method === 'OPTIONS') { res.status(204).end(); return; }
  const q = req.url || '';
  if (q.indexOf('employees=1') >= 0) {
    const allowLive = (req.headers['x-arl-live'] === '1') || (req.headers.host && req.headers.host.indexOf('localhost') === 0);
    if (allowLive) {
      try {
        const sql = (await import('mssql')).default;
        const pool = await sql.connect({ user: process.env.MSSQL_USER || 'mcp_user', password: process.env.MSSQL_PASSWORD, server: process.env.MSSQL_SERVER || '203.202.241.211', port: parseInt(process.env.MSSQL_PORT || '1433', 10), database: process.env.MSSQL_DATABASE || 'DWH', options: { encrypt: false, trustServerCertificate: true }, requestTimeout: 8000, connectionTimeout: 3000 });
        const dirQ = await pool.request().query(`SELECT TOP 2500 e.intEmployeeBasicInfoId AS eid, e.strEmployeeCode AS code, e.strEmployeeName AS name, ISNULL(md.strDepartment,'') AS dept, ISNULL(ms.strSectionName,'') AS sec, ISNULL(des.strDesignation,'') AS desig, ISNULL(mb.strBusinessUnit,'') AS sbu, ISNULL(mw.strWorkplace,'') AS workplace, ISNULL(mwg.strWorkplaceGroup,'') AS wg, ISNULL(d.strOfficeMail,'') AS email, ISNULL(d.strOfficeMobile,'') AS mobile, CONVERT(varchar(10), e.dteJoiningDate, 23) AS joined, e.isActive AS act FROM saas.empEmployeeBasicInfoArc e LEFT JOIN saas.empEmployeeBasicInfoDetailsArc d ON e.intEmployeeBasicInfoId=d.intEmployeeId LEFT JOIN saas.masterDepartmentArc md ON e.intDepartmentId=md.intDepartmentId LEFT JOIN saas.masterSectionArc ms ON e.intSectionId=ms.intSectionId LEFT JOIN saas.masterDesignationArc des ON e.intDesignationId=des.intDesignationId LEFT JOIN saas.masterBusinessUnitArc mb ON e.intBusinessUnitId=mb.intBusinessUnitId LEFT JOIN saas.masterWorkplaceArc mw ON e.intWorkplaceId=mw.intWorkplaceId LEFT JOIN saas.masterWorkplaceGroupArc mwg ON e.intWorkplaceGroupId=mwg.intWorkplaceGroupId WHERE e.isActive=1 AND d.strOfficeMail IS NOT NULL AND mb.strBusinessUnit NOT LIKE '%Demo%' ORDER BY e.intEmployeeBasicInfoId`);
        const teamQ = await pool.request().query(`SELECT e.intEmployeeBasicInfoId AS eid, e.strEmployeeCode AS code, e.strEmployeeName AS name, ISNULL(md.strDepartment,'') AS dept, ISNULL(ms.strSectionName,'') AS sec, ISNULL(des.strDesignation,'') AS desig, ISNULL(mb.strBusinessUnit,'') AS sbu, ISNULL(mw.strWorkplace,'') AS workplace, ISNULL(d.strOfficeMail,'') AS email, ISNULL(d.strOfficeMobile,'') AS mobile, CONVERT(varchar(10), e.dteJoiningDate, 23) AS joined, e.isActive AS act FROM saas.empEmployeeBasicInfoArc e LEFT JOIN saas.empEmployeeBasicInfoDetailsArc d ON e.intEmployeeBasicInfoId=d.intEmployeeId LEFT JOIN saas.masterDepartmentArc md ON e.intDepartmentId=md.intDepartmentId LEFT JOIN saas.masterSectionArc ms ON e.intSectionId=ms.intSectionId LEFT JOIN saas.masterDesignationArc des ON e.intDesignationId=des.intDesignationId LEFT JOIN saas.masterBusinessUnitArc mb ON e.intBusinessUnitId=mb.intBusinessUnitId LEFT JOIN saas.masterWorkplaceArc mw ON e.intWorkplaceId=mw.intWorkplaceId WHERE (e.intSupervisorId=557746 OR e.intLineManagerId=557746) AND e.isActive=1 AND mb.strBusinessUnit NOT LIKE '%Demo%' ORDER BY e.strEmployeeName`);
        await pool.close();
        res.status(200).json({ employees: dirQ.recordset, team: teamQ.recordset, source: 'live' });
        return;
      } catch (e) { console.error('employees live error:', e.message); }
    }
    res.status(200).json({ employees: EMPLOYEES, team: TEAM, source: 'snapshot' });
    return;
  }
  // default: manpower sheet
  if (CACHE && Date.now() - CACHE_AT < 30000) { res.status(200).json(CACHE); return; }
  try {
    const resp = await fetch(CSV_URL);
    const text = await resp.text();
    const grid = parseCSV(text);
    if (!grid.length) throw new Error('empty sheet');
    const h = grid[0].map(x => x.trim());
    const nameIdx = h.indexOf('Employee Name');
    const out = grid.slice(1).filter(r => nameIdx >= 0 && r[nameIdx] && r[nameIdx].trim() && r[nameIdx].trim() !== 'Employee Name').map(r => mapRow(r, h));
    CACHE = out; CACHE_AT = Date.now();
    res.status(200).json(out);
  } catch (e) {
    console.error('manpower fetch error:', e.message);
    if (CACHE) { res.status(200).json(CACHE); return; }
    res.status(500).json({ error: e.message });
  }
}